net.coobird.thumbnailator.filters.ImageFilter dummyFilter = new net.coobird.thumbnailator.filters.ImageFilter() {
    @Override
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
        return img;
    }
};

net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
        .size(100, 100)
        .filters(java.util.Collections.singletonList(dummyFilter))
        .build();

java.util.List<net.coobird.thumbnailator.filters.ImageFilter> appliedFilters = param.getImageFilters();

assert appliedFilters != null : "Returned filters list should not be null";
assert appliedFilters.size() == 1 : "Returned filters list should have size 1";
assert appliedFilters.get(0) == dummyFilter : "Returned filter should be the one added";

System.out.println("__CHECK__ getImageFilters " + appliedFilters.size());

